pub static ACTIONS: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(r#"[{"name":"pl.session.start","description":"PL creates a new session from raw_intent. Status starts at clarifying. Lints out decision-defer phrases. Returns {session_id, status, raw_intent, budget_usd}.","owner_agent":"pl","steps_json":"[{\"skill\":\"pl-session-start\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"pl.session.advance.research","description":"PL research step: pulls RAG context (cards/correction-memories/laws) then system.ai.call(pl.research.summary mid+cold) writes why_relevant_md per finding. Persists pl_research_findings rows. Advances researching → deciding_split.","owner_agent":"pl","steps_json":"[{\"skill\":\"pl-session-advance-research\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"pl.session.advance.decompose","description":"PL decompose step: system.ai.call(pl.decompose.decision high+warm) decides is_atomic. If false, spawns child pl_sessions and persists pl_decomposition_children. Advances deciding_split → tuning.","owner_agent":"pl","steps_json":"[{\"skill\":\"pl-session-advance-decompose\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"pl.screening","description":"PIPELINE-V2 PLAN: PL screens a raw card into enriched context + acceptance S-tasks via a 3-SKILL SWARM, each its own audited AI call: pl-screening-research (mid, gathers memory/prior-card context) → pl-screening-clarify (mid, → list of features) → pl-screening-refine (low, decomposes each feature into tiny S-tasks + persists to pl_screenings). input: {card_slug}.","owner_agent":"pl","steps_json":"[{\"skill\":\"with-audit\",\"input\":{\"skill\":\"pl-screening-research\",\"wrappedInput\":{\"card_slug\":\"$.input.card_slug\"},\"operation\":\"pl.screening.research\",\"entity_type\":\"card\",\"entity_id\":\"$.input.card_slug\"},\"as\":\"research\"},{\"skill\":\"with-audit\",\"input\":{\"skill\":\"pl-screening-clarify\",\"wrappedInput\":{\"card_slug\":\"$.input.card_slug\",\"research_md\":\"$.results.research.research_md\"},\"operation\":\"pl.screening.clarify\",\"entity_type\":\"card\",\"entity_id\":\"$.input.card_slug\"},\"as\":\"clarify\"},{\"skill\":\"with-audit\",\"input\":{\"skill\":\"pl-screening-refine\",\"wrappedInput\":{\"card_slug\":\"$.input.card_slug\",\"research_md\":\"$.results.research.research_md\",\"clarify_md\":\"$.results.clarify.clarify_md\"},\"operation\":\"pl.screening.refine\",\"entity_type\":\"card\",\"entity_id\":\"$.input.card_slug\"},\"as\":\"refine\"}]","returns":"$.results.refine","on_failure":"abort"},{"name":"pl.ratify.contract","description":"PIPELINE-V2 PLAN: PL ratifies by COMPARING the contract acceptance (S-tasks, each linked to a card feature via card_acceptance_id) against the card acceptance (the features). Coverage gate (every feature covered) + AI satisfies-check → status pl_ratified, or rejected + rejection_reason_md for the rewind. input: {contract_slug}.","owner_agent":"pl","steps_json":"[{\"skill\":\"with-audit\",\"input\":{\"skill\":\"pl-ratify-contract\",\"wrappedInput\":\"$.input\",\"operation\":\"pl.ratify.contract\",\"entity_type\":\"contract\",\"entity_id\":\"$.input.contract_slug\"},\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"pl.review.contract","description":"PL reads the contract TL drafted; returns {verdict: signed|pushback, pushback_md?}. State machine routes pushback back to tl.contract.redraft. Cap TL_MAX_PL_REVIEWS=2 cycles; MAN arbitrates after.","owner_agent":"pl","steps_json":"[{\"skill\":\"pl-contract-review\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"pl.session.advance.clarify","description":"IN runs elicitation: calls system.ai.call with prompt pl.clarify.questions, persists pl_questions + pl_question_options rows (no JSON). If AI returns confidence_in_understanding ≥ 0.85, skips questions and advances session straight to researching.","owner_agent":"in","steps_json":"[{\"skill\":\"pl-session-advance-clarify\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"pl.session.answer.record","description":"Record an answer to a pl_questions row (selected_option_id OR writein_md). When all questions in the current step are answered, session auto-advances to the next step.","owner_agent":"in","steps_json":"[{\"skill\":\"pl-session-answer-record\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"pl.session.render.questionnaire.md","description":"Render a session's pending pl_questions as a fillable markdown document. Open in any editor; submit via pl.session.answer.record.","owner_agent":"in","steps_json":"[{\"skill\":\"pl-questionnaire-md\",\"input\":\"$.input\",\"as\":\"md\"}]","returns":"$.results.md","on_failure":"abort"},{"name":"pl.session.finalize","description":"Assemble a pl_proposed_cards row from accumulated session data (intent + answers + research findings). Advances status to awaiting_approval. Idempotent: re-running supersedes the prior proposal.","owner_agent":"pl","steps_json":"[{\"skill\":\"pl-session-finalize\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"pl.session.approve","description":"Atomic approval: INSERT into cards + sacred_timeline event + mark proposed=approved + session=done. Returns approved_card_slug.","owner_agent":"pl","steps_json":"[{\"skill\":\"pl-session-approve\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"pl.session.reject","description":"User rejects proposed card. Calls system.learn.insight (NOT memory-add directly) for self-learning. Marks proposed=rejected and session=abandoned.","owner_agent":"pl","steps_json":"[{\"skill\":\"pl-session-reject\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"pl.research","description":"PL research before card drafting: queries memory + knowledge + related cards + synthesizes a structured research report.","owner_agent":"pl","steps_json":"[{\"skill\":\"pl-research\",\"input\":\"$.input\",\"as\":\"report\"}]","returns":"$.results.report","on_failure":"abort"}]"#).expect("ACTIONS: embedded JSON is valid by construction")
});

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;

    #[test]
    fn actions_parses_with_the_pressed_shape() {
        let v: &Value = &ACTIONS;
        let a = v.as_array().expect("array");
        assert_eq!(a.len(), 13, "pressed length");
        let mut names: Vec<&str> = a.iter().map(|x| x["name"].as_str().expect("name")).collect();
        let n = names.len();
        names.sort(); names.dedup();
        assert_eq!(names.len(), n, "names unique");
    }

}
